from("file:incoming?noop=true")
    .routeId("orders-in")
    .log("Got file: ${header.CamelFileName}")
    .process(exchange -> {
        String body = exchange.getMessage().getBody(String.class);
        exchange.getMessage().setHeader("OrderSize", body.length());
    })
    .to("jms:queue:orders.raw");

from("jms:queue:orders.validated")
    .filter(header("CamelOrderTotal").isGreaterThan(0))
    .to("jms:queue:orders.billable");

from("jms:queue:orders.validated")
    .recipientList(header("NotifyChannels"))
        .parallelProcessing();
// header "NotifyChannels" resolved at runtime, e.g. "jms:queue:audit,jms:queue:billing"

from("jms:queue:orders.validated")
    .wireTap("jms:queue:orders.audit-log")
    .to("jms:queue:orders.processing");

from("jms:queue:orders.raw")
    .split(jsonpath("$.lineItems"))
        .to("jms:queue:orders.line-items")
    .end();

from("jms:queue:orders.raw")
    .enrich("http://customer-api/lookup", (original, resource) -> {
        original.getMessage().setHeader("CustomerTier", resource.getMessage().getBody(String.class));
        return original;
    })
    .to("jms:queue:orders.enriched");

package com.example;

import org.apache.camel.builder.RouteBuilder;
import org.springframework.stereotype.Component;

@Component
public class OrderRoute extends RouteBuilder {

    @Override
    public void configure() throws Exception {
        from("timer:orderPoll?period=5000")
            .to("log:orders");
    }
}

from("file:data/incoming?noop=true")
    .routeId("orders-copy")
    .log("Copying ${header.CamelFileName}")
    .to("file:data/outgoing");

public class HeartbeatRoute extends RouteBuilder {
    @Override
    public void configure() {
        from("timer:heartbeat?period=5000")
            .routeId("heartbeat")
            .log("Tick ${exchangeProperty.CamelTimerCounter}");
    }
}

public class OrdersCopyRoute extends RouteBuilder {
    @Override
    public void configure() {
        from("file:data/incoming?noop=true")
            .routeId("orders-copy")
            .log("Copying ${header.CamelFileName}")
            .to("file:data/outgoing");
    }
}

from("direct:validateOrder")
    .process(exchange -> {
        String body = exchange.getMessage().getBody(String.class);
        if (body == null || body.isBlank()) {
            throw new IllegalArgumentException("empty order body");
        }
    });

